def blocks(data):
    out=[]
    for m in spans(data):
        if out and not data[out[-1][1]:m.start()].strip():
            out[-1]=(out[-1][0],m.end())
        else: out.append((m.start(),m.end()))
    return out

def run():
    all_edits={}; reasons={}
    for name,rows in changes.items():
        data=(ROOT/'source/b'/name).read_bytes(); edits=[]
        for prefix,new in rows:
            found=[(a,b) for a,b in blocks(data) if data[a:b].decode('utf-8').startswith('// '+prefix)]
            assert len(found)==1,(name,prefix)
            a,b=found[0]; old=data[a:b].decode('utf-8')
            indentation=data[data.rfind(b'\n',0,a)+1:a].decode('utf-8')
            assert not indentation.strip() or b'//' not in data[:a][-1:], name
            # Inline comments are single-line replacements; their preceding code stays intact.
            indent=indentation if not indentation.strip() else ' '
            text=('\n'+indent).join('// '+line for line in new.splitlines())
            edits.append((old,text))
        all_edits[name]=edits
        reasons[name]='按模块实际协议改写注释，保留数值、帧边界、所有权、延迟及复位约定；去掉版本比较或重复概述。'
    items=list(all_edits)
    for j in range(0,len(items),5):
        names=items[j:j+5]
        apply_batch('b',f'{5+j//5:02d}_continued',{n:all_edits[n] for n in names},{n:reasons[n] for n in names})
    unchanged={p.name:('保留厂商署名/接口短注释或精确参数、卡绑定信息；未发现需改写的模板性说明。' if list(spans(p.read_bytes(),p.suffix=='.vhd')) else '无描述性注释，保持代码及配置原样。') for p in files(ROOT,'b') if p.name not in changes}
    write_json(ROOT/'reports/REVIEW_B_CONTINUED.json',dict(reviewed_files=len(files(ROOT,'b')),changed_here=list(changes),other_files=unchanged,opaque_ip='Excluded: never opened or modified.'))

if __name__=='__main__':run()
